use App\Services\Admin\OrderAdminService as Rules;
$pageTitle='Chi tiết đơn hàng';$e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$money=static fn($v)=>number_format((float)$v,0,',','.').' đ';$next=Rules::next($order['status']);ob_start(); ?>
<a class="text-blue-700 underline" href="/admin/orders">Quay lại danh sách</a><p class="rounded bg-amber-50 p-3 my-3">Mô phỏng trạng thái đơn COD local; không xác nhận thanh toán, tồn kho hoặc giao nhận thực tế.</p><?php if($message!==''): ?><p class="p-3 bg-green-50 text-green-800"><?= $e($message) ?></p><?php endif; ?>
<div class="bg-white rounded border p-4 my-4"><h2 class="font-bold text-xl"><?= $e($order['checkout_key']) ?></h2><p>Email: <?= $e($order['email']??'Không có') ?></p><p>Trạng thái: <?= $e(Rules::LABELS[$order['status']]??$order['status']) ?></p><p>Tiền hàng: <?= $money($order['items_total']) ?></p><p>Thuế: <?= $money($order['tax_total']) ?></p><p>Phí ship: <?= $money($order['shipping_fee']) ?></p><p>COD dự kiến: <?= $money($order['cod_total']) ?></p><p>Thanh toán: Chưa đối soát (dữ liệu mẫu).</p></div>
<div class="overflow-x-auto bg-white border rounded"><table class="w-full text-left text-sm"><thead><tr><?php foreach(['Sản phẩm','SKU','SL','Đơn giá','Thuế','Thành tiền'] as $label): ?><th class="p-3"><?= $e($label) ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach($items as $i): ?><tr class="border-t"><td class="p-3"><?= $e($i['product_name']) ?></td><td class="p-3"><?= $e($i['sku']) ?></td><td class="p-3"><?= (int)$i['quantity'] ?></td><td class="p-3"><?= $money($i['unit_price']) ?></td><td class="p-3"><?= $money($i['line_tax']) ?></td><td class="p-3"><?= $money($i['line_total']) ?></td></tr><?php endforeach; ?></tbody></table></div>
<?php if($next): ?><form class="bg-white rounded border p-4 my-4 space-y-3" method="post" action="/admin/orders/<?= (int)$order['id'] ?>/update"><h2 class="font-bold">Cập nhật trạng thái mô phỏng</h2><input type="hidden" name="token" value="<?= $e($token) ?>"><input type="hidden" name="expected" value="<?= $e($order['status']) ?>"><select name="status" class="border rounded p-2"><?php foreach($next as $s): ?><option value="<?= $e($s) ?>"><?= $e(Rules::LABELS[$s]) ?></option><?php endforeach; ?></select><input class="border rounded p-2 w-full" name="reason" maxlength="255" placeholder="Lý do (bắt buộc khi hủy hoặc giao thất bại)"><button class="bg-blue-600 text-white rounded p-2">Lưu trạng thái</button></form><?php else: ?><p class="my-4">Không còn thao tác chuyển trạng thái.</p><?php endif; ?>
<h2 class="font-bold text-xl my-3">Lịch sử trạng thái</h2><div class="bg-white border rounded p-4"><?php foreach($history as $h): ?><div class="border-b py-2"><?= $e($h['created_at']) ?> · <?= $e(Rules::LABELS[$h['from_status']]??$h['from_status']) ?> → <?= $e(Rules::LABELS[$h['to_status']]??$h['to_status']) ?> · NV #<?= (int)$h['created_by'] ?> · <?= $e($h['reason']) ?></div><?php endforeach; ?><?php if(!$history): ?><p>Chưa có thay đổi.</p><?php endif; ?></div>
